def count_routes(grid: list[str]) -> int:
    ways = [0] * len(grid[0])            # ways[c] = routes into column c of the current row
    ways[0] = 1                          # one way to stand on the start
    for row in grid:
        for c, cell in enumerate(row):
            if cell == "#":
                ways[c] = 0              # nothing passes through a blocked cell
            elif c > 0:
                ways[c] += ways[c - 1]   # from above (the old ways[c]) + from the left
    return ways[-1]
